/**
 * A subdivisão fractal — a curva que fica mais longa sem ocupar mais espaço.
 *
 * É a ideia inteira do módulo, e é uma daquelas que não se aprende num número:
 * a moldura pontilhada NÃO MUDA de tamanho enquanto o traço dentro dela dobra de
 * comprimento a cada nível. A folha, o pulmão e o intestino fazem isso — área de
 * contato enorme empacotada num volume pequeno.
 *
 * A curva desenhada é a de Koch (cada trecho vira quatro). Do nível 7 em diante
 * os trechos ficam menores que um pixel: o desenho para de subdividir e a conta
 * continua, porque é ela que o puzzle mede.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  ptBR,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Além disto o traço vira mancha: o desenho para, a conta não. */
const NIVEL_MAXIMO_DESENHAVEL = 6;

type Ponto = readonly [number, number];

/** A curva de Koch normalizada em x ∈ [0,1], y para cima. Uma vez por nível. */
const cache = new Map<number, Ponto[]>();

function koch(nivel: number): Ponto[] {
  const guardada = cache.get(nivel);
  if (guardada !== undefined) return guardada;

  let pontos: Ponto[] = [
    [0, 0],
    [1, 0],
  ];

  for (let passo = 0; passo < nivel; passo++) {
    const proximos: Ponto[] = [];
    for (let i = 0; i < pontos.length - 1; i++) {
      const a = pontos[i];
      const b = pontos[i + 1];
      if (a === undefined || b === undefined) continue;

      const dx = (b[0] - a[0]) / 3;
      const dy = (b[1] - a[1]) / 3;
      const p1: Ponto = [a[0] + dx, a[1] + dy];
      const p3: Ponto = [a[0] + dx * 2, a[1] + dy * 2];
      // O bico: o terço do meio girado 60°, que é o que cria o comprimento novo.
      const cos = Math.cos(Math.PI / 3);
      const sen = Math.sin(Math.PI / 3);
      const p2: Ponto = [p1[0] + dx * cos - dy * sen, p1[1] + dx * sen + dy * cos];

      proximos.push(a, p1, p2, p3);
    }
    const ultimo = pontos[pontos.length - 1];
    if (ultimo !== undefined) proximos.push(ultimo);
    pontos = proximos;
  }

  cache.set(nivel, pontos);
  return pontos;
}

const fractal: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const nivel = Math.max(0, Math.trunc(numeroDe(valores, 'n', 0)));
    const area = numeroDe(info, 'area', 2 ** nivel);
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : cor.azul;

    titulo(ctx, L, A, 'Mais área de contato, no mesmo espaço');

    // ── A moldura que não cresce ─────────────────────────────────────────
    const x0 = L * 0.1;
    const x1 = L * 0.9;
    const largura = x1 - x0;
    const alturaCurva = largura * 0.42;
    const yBase = A * 0.63;

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.4;
    ctx.setLineDash([5, 4]);
    ctx.strokeRect(x0, yBase - alturaCurva, largura, alturaCurva);
    ctx.setLineDash([]);

    const miudo = limitar(A * 0.032, 8, 11);
    texto(ctx, 'o espaço ocupado não muda', L / 2, yBase - alturaCurva - miudo, miudo, {
      cor: cor.fraco,
      peso: 600,
    });

    // ── A curva ──────────────────────────────────────────────────────────
    const desenhavel = Math.min(nivel, NIVEL_MAXIMO_DESENHAVEL);
    const pontos = koch(desenhavel);

    // A curva de Koch sobe até ~0,289 do vão; a escala a prende na moldura.
    const escalaY = alturaCurva / 0.32;

    ctx.strokeStyle = tinta;
    ctx.lineWidth = desenhavel >= 5 ? 1 : 2.2;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (const [i, p] of pontos.entries()) {
      const px = x0 + p[0] * largura;
      const py = yBase - p[1] * escalaY;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();

    // A corda: o vão em linha reta, a base da comparação.
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x0, yBase);
    ctx.lineTo(x1, yBase);
    ctx.stroke();

    // ── A régua dos níveis ───────────────────────────────────────────────
    const yRegua = A * 0.78;
    const alturaRegua = limitar(A * 0.045, 8, 14);
    const teto = 12;

    retangulo(ctx, x0, yRegua, largura, alturaRegua, alturaRegua / 2, cor.palha, cor.trilho, 1);
    retangulo(
      ctx,
      x0,
      yRegua,
      (limitar(nivel, 0, teto) / teto) * largura,
      alturaRegua,
      alturaRegua / 2,
      tinta,
    );

    for (let n = 0; n <= teto; n += 2) {
      texto(ctx, `${n}`, x0 + (n / teto) * largura, yRegua + alturaRegua + miudo, miudo, {
        cor: cor.fraco,
      });
    }
    texto(ctx, 'nível de subdivisão', L / 2, yRegua - miudo * 1.1, miudo, {
      cor: cor.fraco,
      peso: 600,
    });

    // ── A conta ──────────────────────────────────────────────────────────
    const medio = limitar(A * 0.05, 11, 16);
    texto(ctx, `2^${nivel} = ${ptBR(area)}× a área de contato`, L / 2, A * 0.885, medio, {
      cor: tinta,
      peso: 800,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Área de contato suficiente ✔',
      nivel > NIVEL_MAXIMO_DESENHAVEL
        ? 'Os trechos já são menores que um pixel — o desenho parou, a conta não.'
        : 'Cada subdivisão dobra a área: continue subindo o nível.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default fractal;
